package com.nextaicommerce.platform.fba;
import static org.junit.jupiter.api.Assertions.*;import static com.nextaicommerce.platform.fba.FbaReplenishmentMath.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class FbaIncomingPositionTest{
 final LocalDate today=LocalDate.of(2026,11,19);final Policy policy=Policy.defaults();final Demand demand=new Demand(72.33333333333333,217,90,null,null);
 @Test void belinayKnownUndated142OffsetsAdditionalRecommendationWithoutChangingCurrentStockout(){var old=estimate(today,demand,policy,55d,false,100,List.of(),List.of());var fixed=estimate(today,demand,policy,55d,false,100,List.of(new FutureSupply(142,null,false,true)),List.of());assertEquals(90,old.recommended());assertEquals(0,fixed.recommended());assertEquals(old.cover(),fixed.cover());assertEquals(old.stockout(),fixed.stockout());assertNull(fixed.arrival());assertTrue(fixed.warnings().stream().anyMatch(w->w.contains("arrival")||w.contains("Arrival")));}
 @Test void legacyUntrustedUndatedQuantityDoesNotOffset(){var r=estimate(today,demand,policy,55d,false,100,List.of(new FutureSupply(1000,null,false)),List.of());assertEquals(90,r.recommended());}
 @Test void aSmallerCommitmentReducesOnlyTheAdditionalUnits(){var r=estimate(today,demand,policy,55d,false,100,List.of(new FutureSupply(40,null,false,true)),List.of());assertEquals(50,r.recommended());}
 @Test void verifiedDatedReceiptAfterOwnArrivalButInsideTargetOffsetsOnce(){var r=estimate(today,demand,new Policy(28,60,0,0,0,null,true),55d,false,100,List.of(new FutureSupply(142,today.plusDays(30),true,true)),List.of());assertEquals(0,r.recommended());assertEquals(today.plusDays(22),r.stockout());}
 @Test void receiptAtOrBeyondTargetEndAndPastReceiptNeverOffsetsAgain(){for(var day:List.of(today.minusDays(1),today.plusDays(60),today.plusDays(61))){var r=estimate(today,demand,new Policy(28,60,0,0,0,null,true),55d,false,100,List.of(new FutureSupply(142,day,true,true)),List.of());assertEquals(90,r.recommended());}}
 @Test void datedReceiptAlreadyInProjectedArrivalIsNotSubtractedTwice(){var p=new Policy(28,60,10,0,0,null,true);var old=estimate(today,demand,p,55d,false,100,List.of(new FutureSupply(40,today.plusDays(5),true)),List.of());var current=estimate(today,demand,p,55d,false,100,List.of(new FutureSupply(40,today.plusDays(5),true,true)),List.of());assertEquals(old.recommended(),current.recommended());}
 @Test void staleInventoryNeverBecomesZeroRecommendationFromLargeCommitment(){assertNull(estimate(today,demand,policy,55d,true,100,List.of(new FutureSupply(1000,null,false,true)),List.of()).recommended());}
 @Test void receiptDatedTodayIsNeverRecreditedToObservedStockOrAdditionalQuantity(){var p=new Policy(28,60,0,0,0,null,true);var base=estimate(today,demand,p,55d,false,100,List.of(),List.of());for(boolean verified:List.of(false,true)){var value=estimate(today,demand,p,55d,false,100,List.of(new FutureSupply(142,today,verified,true)),List.of());assertEquals(base.recommended(),value.recommended());assertEquals(base.cover(),value.cover());assertEquals(base.stockout(),value.stockout());}}
}
